'use strict';
const $=id=>document.getElementById(id);
const DB_NAME='anbarshomar-offline-android-v1';
const COMPANY={1:'بسپار شیمی',2:'سپید شیمی'};
const MAX_QTY=9000000000000;
let db,products=[],entries=[],settings={companyId:1,warehouse:'',period:'',operator:''},raw=null;
let currentRound=1,selected=null,saving=false,exporting=false,staged=null,toastTimer;
const nativeSaves=new Map();
const nativePicks=new Map();
let nativePicking=false;
const en=s=>String(s??'').replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c));
const norm=s=>en(s).replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[\u200c\u200e\u200f\u061c]/g,' ').replace(/\s+/g,' ').trim().toLowerCase();
const ident=s=>en(s).replace(/[\u200c\u200e\u200f\u061c\s]/g,'');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('fa-IR',{maximumFractionDigits:3}).format(n);
function uid(){if(crypto.randomUUID)return crypto.randomUUID();return Array.from(crypto.getRandomValues(new Uint8Array(24)),n=>n.toString(16).padStart(2,'0')).join('');}
function notify(msg,error=false){$('toast').textContent=msg;$('toast').className=error?'error-toast':'';$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,7000);}
function fail(message){$('fatal').hidden=false;$('fatal').innerHTML=`<h2>برنامه آماده نشد</h2><p>${esc(message)}</p><p>داده‌های برنامه را پاک نکنید؛ برنامه را ببندید و دوباره باز کنید.</p>`;}
function parseQty(value){const s=en(value).replace(/٫/g,'.').replace(/٬/g,'').trim();if(!/^\d+(?:\.\d{1,3})?$/.test(s))throw Error('عدد صفر یا بیشتر، با حداکثر سه رقم اعشار وارد کنید.');const [a,b='']=s.split('.');const n=Number(a)*1000+Number(b.padEnd(3,'0'));if(!Number.isSafeInteger(n)||n>MAX_QTY)throw Error('تعداد از محدوده مجاز بیشتر است.');return n;}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{const d=r.result;d.createObjectStore('meta',{keyPath:'key'});d.createObjectStore('products',{keyPath:'id'});d.createObjectStore('entries',{keyPath:'id'});};r.onsuccess=()=>{r.result.onversionchange=()=>r.result.close();resolve(r.result);};r.onerror=()=>reject(r.error||Error('پایگاه داده گوشی باز نشد.'));r.onblocked=()=>reject(Error('نسخه دیگری از برنامه باز است. ابتدا آن را ببندید.'));});}
function write(stores,enqueue){return new Promise((resolve,reject)=>{let tx,result,problem;try{try{tx=db.transaction(stores,'readwrite',{durability:'strict'});}catch{tx=db.transaction(stores,'readwrite');}const done=x=>result=x;const stop=e=>{problem=e;tx.abort();};enqueue(tx,done,stop);tx.oncomplete=()=>resolve(result);tx.onabort=()=>reject(problem||tx.error||Error('ذخیره انجام نشد؛ حافظهٔ گوشی را بررسی کنید.'));tx.onerror=()=>{};}catch(e){if(tx)try{tx.abort();}catch{}reject(e);}});}
function snapshot(){return new Promise((resolve,reject)=>{const tx=db.transaction(['meta','products','entries'],'readonly'),m=tx.objectStore('meta'),out={};m.get('settings').onsuccess=e=>out.settings=e.target.result?.value||settings;m.get('raw').onsuccess=e=>out.raw=e.target.result?.value||null;tx.objectStore('products').getAll().onsuccess=e=>out.products=e.target.result;tx.objectStore('entries').getAll().onsuccess=e=>out.entries=e.target.result;tx.oncomplete=()=>resolve(out);tx.onabort=()=>reject(tx.error||Error('خواندن اطلاعات کامل نشد.'));});}
async function reload(){const s=await snapshot();({products,entries,settings,raw}=s);entries.sort((a,b)=>b.createdAt.localeCompare(a.createdAt)||b.id.localeCompare(a.id));render();}
function totalFor(id,round=currentRound,list=entries){const found=list.filter(e=>e.productId===id&&e.round===round);if(!found.length)return null;return found.reduce((n,e)=>n+e.qtyMilli,0);}
function render(){
 $('context').textContent=settings.warehouse?`${COMPANY[settings.companyId]} · ${settings.warehouse}${settings.period?' · '+settings.period:''}`:'ابتدا مشخصات شمارش را در تنظیمات ثبت کنید.';
 $('productCount').textContent=fmt(products.length);$('entryCount').textContent=fmt(entries.filter(e=>e.round===currentRound).length);
 $('fileStatus').textContent=raw?`فایل واردشده: ${raw.fileName} · ${fmt(products.filter(p=>p.sourceRow).length)} ردیف خام`:'هنوز فایل خامی وارد نشده است.';
 renderSearch();const mine=entries.filter(e=>e.operator===settings.operator&&e.round===currentRound),seen=new Set(),recent=[];for(const e of mine){if(seen.has(e.productId))continue;seen.add(e.productId);recent.push(e);if(recent.length===3)break;}
 $('recent').innerHTML=recent.map(e=>{const p=products.find(p=>p.id===e.productId);return p?`<div class="recent-item"><div><h3>${esc(p.name)}</h3><div class="meta">${esc(e.operator)} · ${new Date(e.createdAt).toLocaleString('fa-IR')}</div></div><button data-pick="${esc(p.id)}" class="badge">${fmt(e.qtyMilli/1000)}</button></div>`:'';}).join('')||'<p class="empty">در این نوبت هنوز کالایی ثبت نکرده‌اید.</p>';
}
function showTab(tab){for(const s of document.querySelectorAll('section[id^="tab-"]'))s.hidden=s.id!==`tab-${tab}`;for(const b of document.querySelectorAll('[data-tab]'))b.classList.toggle('active',b.dataset.tab===tab);if(tab==='settings'){for(const [id,value]of Object.entries({company:settings.companyId,warehouse:settings.warehouse,period:settings.period,operator:settings.operator}))$(id).value=value;for(const id of ['company','warehouse','period'])$(id).disabled=products.length>0;}if(tab==='count')$('search').focus();}
async function saveSettings(){const next={companyId:Number($('company').value),warehouse:$('warehouse').value.trim(),period:$('period').value.trim(),operator:$('operator').value.trim()};if(!COMPANY[next.companyId]||!next.warehouse||!next.operator)throw Error('شرکت، نام انبار و نام شمارشگر را وارد کنید.');if(products.length&&(next.companyId!==settings.companyId||next.warehouse!==settings.warehouse||next.period!==settings.period))throw Error('شرکت و انبار پس از ورود کالا قابل تغییر نیستند.');await write(['meta'],tx=>tx.objectStore('meta').put({key:'settings',value:next}));await reload();showTab('count');notify('مشخصات ذخیره شد.');}
function matches(p,query,mode){if(mode==='tag')return ident(p.tag)!==''&&ident(p.tag)===ident(query);if(mode==='code')return norm(p.code).includes(norm(query));return norm(p.name).includes(norm(query));}
function productHTML(p){const t=totalFor(p.id);return `<div class="product"><div><h3>${esc(p.name)}</h3><div class="meta">${p.tag?`<span>تگ: <code>${esc(p.tag)}</code></span>`:''}${p.code?`<span>کد: <code>${esc(p.code)}</code></span>`:''}</div><span class="badge ${t===null?'unset':''}">${t===null?'شمارش نشده':fmt(t/1000)}</span></div><button class="primary" data-pick="${esc(p.id)}">شمارش</button></div>`;}
function renderSearch(){const q=$('search').value.trim();if(!q){$('results').innerHTML='<p class="empty">برای دیدن کالا، تگ، کد یا نام آن را جست‌وجو کنید.</p>';return;}const all=products.filter(p=>matches(p,q,$('searchMode').value));$('results').innerHTML=all.slice(0,40).map(productHTML).join('')||'<p class="empty">کالایی پیدا نشد.</p>';if(all.length>40)$('results').insertAdjacentHTML('beforeend','<p class="help">۴۰ نتیجهٔ اول نمایش داده شد؛ عبارت دقیق‌تری وارد کنید.</p>');}
function modal(title,body){$('modalTitle').textContent=title;$('modalBody').innerHTML=body;if(!$('modal').open)$('modal').showModal();}
function closeModal(){if(saving)return;$('modal').close();selected=null;}
function showCount(id){const p=products.find(p=>p.id===id);if(!p)return;selected=id;const t=totalFor(id);modal('ثبت شمارش',`<h3>${esc(p.name)}</h3><div class="meta"><span>کد: <code>${esc(p.code||'—')}</code></span><span>تگ: <code>${esc(p.tag||'—')}</code></span></div>${p.stock!==''&&p.stock!==undefined?`<span class="stock">موجودی سیستم: ${esc(p.stock)}</span>`:''}<div class="total"><span>جمع نوبت ${fmt(currentRound)}</span><b>${t===null?'—':fmt(t/1000)}</b></div><label for="quantity">تعداد این بخش از کالا</label><input id="quantity" class="count-input" type="text" inputmode="decimal" autocomplete="off" placeholder="۰"><button id="calcToggle" class="secondary wide">ماشین‌حساب</button><div id="calc" hidden><div class="calc-screen" id="calcScreen">0</div><div class="calc-grid">${['7','8','9','/','4','5','6','*','1','2','3','-','C','0','.','+','=','←'].map(x=>`<button data-calc="${x}">${x}</button>`).join('')}</div><button id="useCalc" class="secondary wide">انتقال نتیجه به تعداد</button></div><div id="countError" class="error" hidden></div><button id="saveCount" class="primary wide">ثبت و افزودن به جمع قبلی</button><div id="entryList"></div>`);renderEntries();$('saveCount').onclick=saveCount;$('calcToggle').onclick=()=>$('calc').hidden=!$('calc').hidden;$('calc').onclick=calculatorClick;$('useCalc').onclick=()=>{try{$('quantity').value=String(Math.round(arithmetic($('calcScreen').textContent)*1000)/1000);$('calc').hidden=true;$('quantity').focus();}catch(e){countError(e.message);}};$('quantity').focus();}
function countError(msg){if($('countError')){$('countError').hidden=false;$('countError').textContent=msg;}else notify(msg,true);}
function renderEntries(){const list=entries.filter(e=>e.productId===selected&&e.round===currentRound);$('entryList').innerHTML=list.length?'<h2 style="margin-top:24px">ثبت‌های همین کالا در این نوبت</h2>'+list.map(e=>`<div class="entry"><div class="entry-top"><span>${fmt(e.qtyMilli/1000)} · ${esc(e.operator)}</span><button data-edit="${esc(e.id)}">اصلاح</button></div><small>${new Date(e.createdAt).toLocaleString('fa-IR')}${e.revision>1?` · ${fmt(e.revision-1)} اصلاح`:''}</small><div id="edit-${esc(e.id)}"></div></div>`).join(''):'';}
async function saveCount(){if(saving||!selected)return;const productId=selected,round=currentRound;let quantity;try{quantity=parseQty($('quantity').value);if(!settings.warehouse||!settings.operator)throw Error('مشخصات انبار و شمارشگر را ثبت کنید.');}catch(e){countError(e.message);return;}saving=true;$('saveCount').disabled=true;const entry={id:uid(),productId,round,qtyMilli:quantity,operator:settings.operator,createdAt:new Date().toISOString(),revision:1,changes:[]};try{await write(['entries','products'],(tx,done,stop)=>{const p=tx.objectStore('products').get(productId);p.onsuccess=()=>{if(!p.result){stop(Error('کالا دیگر در این انبار موجود نیست.'));return;}const req=tx.objectStore('entries').getAll();req.onsuccess=()=>{const sum=totalFor(productId,round,req.result)||0;if(sum+quantity>MAX_QTY){stop(Error('جمع تعداد از محدودهٔ مجاز بیشتر است.'));return;}tx.objectStore('entries').add(entry);};};});await reload();saving=false;closeModal();$('search').value='';renderSearch();notify('شمارش روی گوشی ذخیره شد.');$('search').focus();}catch(e){saving=false;if($('saveCount'))$('saveCount').disabled=false;countError('ثبت انجام نشد: '+e.message);}}
function editEntry(id){if(saving)return;const e=entries.find(e=>e.id===id);if(!e)return;const slot=$('edit-'+id);slot.innerHTML=`<div class="entry-edit"><input id="value-${esc(id)}" inputmode="decimal" value="${e.qtyMilli/1000}"><button class="primary" id="correct-${esc(id)}">ذخیره اصلاح</button></div>`;$('correct-'+id).onclick=()=>correctEntry(e);}
async function correctEntry(previous){if(saving)return;let next;try{next=parseQty($('value-'+previous.id).value);}catch(e){countError(e.message);return;}saving=true;$('correct-'+previous.id).disabled=true;try{await write(['entries'],(tx,done,stop)=>{const store=tx.objectStore('entries'),get=store.get(previous.id);get.onsuccess=()=>{const old=get.result;if(!old||old.revision!==previous.revision){stop(Error('این ثبت تغییر کرده؛ فرم را ببندید و دوباره باز کنید.'));return;}const all=store.getAll();all.onsuccess=()=>{const total=(totalFor(old.productId,old.round,all.result)||0)-old.qtyMilli+next;if(total>MAX_QTY){stop(Error('جمع از محدودهٔ مجاز بیشتر است.'));return;}store.put({...old,qtyMilli:next,revision:old.revision+1,updatedAt:new Date().toISOString(),changes:[...(old.changes||[]),{at:new Date().toISOString(),by:settings.operator,from:old.qtyMilli,to:next}]});};};});const pid=selected;await reload();saving=false;showCount(pid);notify('فقط همین ثبت اصلاح شد؛ باقی ثبت‌ها حفظ شدند.');}catch(e){saving=false;countError(e.message);if($('correct-'+previous.id))$('correct-'+previous.id).disabled=false;}}
function arithmetic(expr){const s=en(expr).replace(/\s/g,'');if(!/^\d+(?:\.\d+)?(?:[+*/-]\d+(?:\.\d+)?)*$/.test(s))throw Error('عبارت ماشین‌حساب کامل نیست.');const parts=s.match(/\d+(?:\.\d+)?|[+*/-]/g).map(x=>/^\d/.test(x)?Number(x):x);for(let i=1;i<parts.length-1;){if(parts[i]==='*'||parts[i]==='/'){parts.splice(i-1,3,parts[i]==='*'?parts[i-1]*parts[i+1]:parts[i-1]/parts[i+1]);i=1;}else i+=2;}let n=parts[0];for(let i=1;i<parts.length;i+=2)n=parts[i]==='+'?n+parts[i+1]:n-parts[i+1];if(!Number.isFinite(n)||n<0)throw Error('حاصل باید عدد معتبر و غیرمنفی باشد.');return n;}
function calculatorClick(ev){const b=ev.target.closest('[data-calc]');if(!b)return;let s=$('calcScreen').textContent,v=b.dataset.calc;if(v==='C')s='0';else if(v==='←')s=s.slice(0,-1)||'0';else if(v==='='){try{s=String(Math.round(arithmetic(s)*1000)/1000);}catch(e){countError(e.message);}}else s=s==='0'&&/\d/.test(v)?v:s+v;$('calcScreen').textContent=s;}
function cellText(cell,isIdentifier=false){let v=cell?.value;if(v&&typeof v==='object')v=v.result??v.text??(v.richText?v.richText.map(x=>x.text).join(''):'');if(v===null||v===undefined)return '';if(isIdentifier&&typeof v==='number'){if(!Number.isSafeInteger(v))throw Error('کد یا تگ عددی نامعتبر است؛ ستون مربوطه را در اکسل به متن تبدیل کنید.');const f=(cell.numFmt||'').trim();if(/^0{2,}$/.test(f))return String(v).padStart(f.length,'0');}return String(v).trim();}
function headingScore(x,kind){const s=norm(x).replace(/[\s_:()-]/g,'');const names={name:['نامکالا','عنوانکالا','شرحکالا','ناممحصول','شرحمحصول','نام','عنوان','شرح','itemname','productname','description'],code:['کدکالا','کدمحصول','کد','شناسهکالا','itemcode','productcode','sku'],tag:['شمارهتگ','تگ','شمارهبرچسب','tag','tagno'],stock:['موجودیسیستم','موجودی','موجودیانبار','stock','systemstock']};if(names[kind].includes(s))return 20;return names[kind].some(n=>n.length>=5&&s.includes(n))?10:0;}
function guessSheet(book){let best=null;for(const ws of book.worksheets)for(let r=1;r<=Math.min(25,ws.rowCount);r++){const guess=guessColumns(ws,r),score=Object.entries(guess).reduce((n,[kind,c])=>n+(c?headingScore(cellText(ws.getRow(r).getCell(c)),kind):0),0);if(guess.name&&(!best||score>best.score))best={sheetId:ws.id,headerRow:r,...guess,score};}return best||{sheetId:book.worksheets[0]?.id,headerRow:1,name:1,code:null,tag:null,stock:null};}
function guessColumns(ws,r){const out={};for(const kind of ['name','code','tag','stock']){let best=0,col=null,ambiguous=false;for(let c=1;c<=Math.min(ws.columnCount,100);c++){const s=headingScore(cellText(ws.getRow(r).getCell(c)),kind);if(s>best){best=s;col=c;ambiguous=false;}else if(s&&s===best)ambiguous=true;}out[kind]=ambiguous?null:col;}return out;}
async function readFileBuffer(file){if(file.arrayBuffer)return file.arrayBuffer();return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsArrayBuffer(file);});}
async function beginImport(){const file=$('rawFile').files[0];if(!file)throw Error('فایل اکسل را انتخاب کنید.');if(!settings.warehouse||!settings.operator)throw Error('ابتدا مشخصات انبار و شمارشگر را ذخیره کنید.');if(products.length)throw Error('برای حفظ شمارش‌ها، فایل خام این نصب قابل جایگزینی نیست.');if(!/\.xlsx$/i.test(file.name))throw Error('فقط XLSX پشتیبانی می‌شود؛ فایل XLS را ابتدا در اکسل به XLSX تبدیل کنید.');if(file.size>15*1024*1024)throw Error('حجم فایل باید کمتر از ۱۵ مگابایت باشد.');$('importBtn').disabled=true;try{const bytes=await readFileBuffer(file),book=new ExcelJS.Workbook();await book.xlsx.load(bytes);if(!book.worksheets.length)throw Error('فایل اکسل برگه‌ای ندارد.');staged={book,bytes,fileName:file.name,mapping:guessSheet(book)};showMapping();}finally{$('importBtn').disabled=false;}}
function showMapping(){const m=staged.mapping,ws=staged.book.getWorksheet(m.sheetId);modal('تأیید ستون‌های فایل',`<p class="help">ستون‌ها را بررسی کنید؛ نام کالا اجباری است. صفرهای کد و تگ حفظ می‌شوند.</p><label>برگه<select id="mapSheet">${staged.book.worksheets.map(w=>`<option value="${w.id}" ${w.id===m.sheetId?'selected':''}>${esc(w.name)}</option>`).join('')}</select></label><label>شمارهٔ ردیف عنوان<input id="headerRow" inputmode="numeric" type="number" min="1" max="100" value="${m.headerRow}"></label><div class="mapping">${[['name','نام کالا'],['code','کد کالا'],['tag','شماره تگ'],['stock','موجودی سیستم']].map(([key,label])=>`<label>${label}<select id="map-${key}"><option value="">انتخاب نشده</option>${Array.from({length:Math.min(ws.columnCount,100)},(_,i)=>`<option value="${i+1}" ${m[key]===i+1?'selected':''}>${i+1}: ${esc(cellText(ws.getRow(m.headerRow).getCell(i+1))||'بدون عنوان')}</option>`).join('')}</select></label>`).join('')}</div><div class="preview"><table>${Array.from({length:Math.min(5,ws.rowCount-m.headerRow+1)},(_,i)=>'<tr>'+Array.from({length:Math.min(6,ws.columnCount)},(_,c)=>`<td>${esc(cellText(ws.getRow(m.headerRow+i).getCell(c+1)))}</td>`).join('')+'</tr>').join('')}</table></div><p id="importError" class="error" hidden></p><button id="confirmImport" class="primary wide">تأیید و ورود کالاها</button>`);$('mapSheet').onchange=()=>{const w=staged.book.getWorksheet(Number($('mapSheet').value));staged.mapping={sheetId:w.id,headerRow:1,...guessColumns(w,1)};showMapping();};$('headerRow').onchange=()=>{const r=Number($('headerRow').value);if(Number.isInteger(r)&&r>=1&&r<=100){staged.mapping={sheetId:m.sheetId,headerRow:r,...guessColumns(ws,r)};showMapping();}};$('confirmImport').onclick=()=>commitImport().catch(e=>{$('importError').hidden=false;$('importError').textContent=e.message;$('confirmImport').disabled=false;});}
function parseProducts(ws,mapping){const out=[],seen=new Map();for(let r=mapping.headerRow+1;r<=ws.rowCount;r++){const row=ws.getRow(r),name=cellText(row.getCell(mapping.name)),code=mapping.code?cellText(row.getCell(mapping.code),true):'',tag=mapping.tag?cellText(row.getCell(mapping.tag),true):'';if(!name&&!code&&!tag)continue;if(!name)throw Error(`نام کالا در ردیف ${r} خالی است؛ هیچ کالایی وارد نشد.`);if(name.length>500||code.length>100||tag.length>100)throw Error(`متن ردیف ${r} بیش از حد طولانی است.`);const key=tag?'t:'+ident(tag):code?'c:'+norm(code):'n:'+norm(name);if(seen.has(key))throw Error(`شناسهٔ تکراری در ردیف‌های ${seen.get(key)} و ${r}. برای هر ردیف، تگ یکتا یا کد یکتا لازم است.`);seen.set(key,r);out.push({id:uid(),key,name,code,tag,stock:mapping.stock?cellText(row.getCell(mapping.stock)):'',sourceRow:r});if(out.length>20000)throw Error('حداکثر ۲۰٬۰۰۰ ردیف کالا مجاز است.');}if(!out.length)throw Error('کالایی در ستون‌های انتخاب‌شده پیدا نشد.');return out;}
async function commitImport(){if(saving)return;$('confirmImport').disabled=true;const m={sheetId:Number($('mapSheet').value),headerRow:Number($('headerRow').value)};for(const k of ['name','code','tag','stock'])m[k]=$('map-'+k).value?Number($('map-'+k).value):null;if(!m.name)throw Error('ستون نام کالا را مشخص کنید.');const cols=['name','code','tag','stock'].map(k=>m[k]).filter(Boolean);if(new Set(cols).size!==cols.length)throw Error('برای هر مشخصه، ستون جداگانه انتخاب کنید.');const parsed=parseProducts(staged.book.getWorksheet(m.sheetId),m);saving=true;try{await write(['products','meta'],(tx,done,stop)=>{const p=tx.objectStore('products'),r=p.count();r.onsuccess=()=>{if(r.result){stop(Error('فایل قبلاً وارد شده است.'));return;}for(const product of parsed)p.add(product);tx.objectStore('meta').put({key:'raw',value:{fileName:staged.fileName,bytes:staged.bytes,mapping:m,importedAt:new Date().toISOString()}});};});await reload();staged=null;$('rawFile').value='';saving=false;closeModal();showTab('count');notify(`${fmt(products.length)} کالا وارد شد. آمادهٔ شمارش است.`);}catch(e){saving=false;throw e;}}
function showManual(){if(!settings.warehouse||!settings.operator){notify('ابتدا مشخصات شمارش را ذخیره کنید.',true);showTab('settings');return;}modal('افزودن کالای خارج از فایل',`<label>نام کالا<input id="manualName" maxlength="500"></label><label>کد کالا (اختیاری)<input id="manualCode" maxlength="100"></label><label>تگ (اختیاری)<input id="manualTag" maxlength="100"></label><p id="manualError" class="error" hidden></p><button id="saveManual" class="primary wide">افزودن و رفتن به شمارش</button>`);$('saveManual').onclick=async()=>{if(saving)return;const name=$('manualName').value.trim(),code=ident($('manualCode').value),tag=ident($('manualTag').value);if(!name){$('manualError').hidden=false;$('manualError').textContent='نام کالا را وارد کنید.';return;}const p={id:uid(),name,code,tag,key:tag?'t:'+tag:code?'c:'+norm(code):'n:'+norm(name),stock:'',sourceRow:null};saving=true;$('saveManual').disabled=true;try{await write(['products'],(tx,done,stop)=>{const store=tx.objectStore('products'),all=store.getAll();all.onsuccess=()=>{if(all.result.length>=20000){stop(Error('ظرفیت ۲۰٬۰۰۰ کالای این نصب پر شده است.'));return;}if(all.result.some(x=>x.key===p.key)){stop(Error('این کالا یا شناسه از قبل وجود دارد؛ آن را جست‌وجو کنید.'));return;}store.add(p);};});await reload();saving=false;showCount(p.id);}catch(e){saving=false;$('saveManual').disabled=false;$('manualError').hidden=false;$('manualError').textContent=e.message;}};}
function bytes64(buffer){const b=new Uint8Array(buffer);let s='';for(let i=0;i<b.length;i+=32768)s+=String.fromCharCode(...b.subarray(i,i+32768));return btoa(s);}
function from64(s){const b=atob(s),a=new Uint8Array(b.length);for(let i=0;i<b.length;i++)a[i]=b.charCodeAt(i);return a.buffer;}
const safeName=s=>String(s||'انبار').replace(/[<>:"\\/|?*\u0000-\u001f]/g,'-').slice(0,55);
function saveFile(bytes,mime,name){return window.presentFileSave(bytes,mime,name);}
window.nativeSaveResult=(id,ok,message)=>{const p=nativeSaves.get(id);if(!p)return;nativeSaves.delete(id);if(ok)p.resolve();else p.reject(Error(message||'ذخیرهٔ فایل لغو شد.'));};
async function buildExcel(s){const book=new ExcelJS.Workbook();let ws,m;if(s.raw){await book.xlsx.load(s.raw.bytes);m={...s.raw.mapping};ws=book.getWorksheet(m.sheetId);if(!ws)throw Error('برگهٔ فایل خام پیدا نشد.');}else{ws=book.addWorksheet('شمارش انبار');ws.addRow(['شماره تگ','کد کالا','نام کالا','موجودی سیستم']);m={name:3,code:2,tag:1,stock:4,headerRow:1,sheetId:ws.id};}
 const addedIdentifiers=[];for(const [key,title] of [['code','کد کالا'],['tag','شماره تگ']])if(!m[key]&&s.products.some(p=>p[key])){m[key]=ws.columnCount+1;ws.getRow(m.headerRow).getCell(m[key]).value=title;addedIdentifiers.push(key);}for(const p of s.products)if(p.sourceRow)for(const key of addedIdentifiers)ws.getRow(p.sourceRow).getCell(m[key]).value=p[key];
 const countCols=[];let last=ws.columnCount;for(let r=1;r<=3;r++){let found=null;for(let c=1;c<=ws.columnCount;c++){if(norm(cellText(ws.getRow(m.headerRow).getCell(c)))===`شمارش ${r}`){found=c;break;}}countCols.push(found||++last);const h=ws.getRow(m.headerRow).getCell(countCols[r-1]);h.value=`شمارش ${fmt(r)}`;h.font={...h.font,bold:true,color:{argb:'FF125C82'}};ws.getColumn(countCols[r-1]).numFmt='#,##0.###';ws.getColumn(countCols[r-1]).width=17;}
 const totals=new Map();for(const e of s.entries){const key=e.productId+'|'+e.round,prev=totals.get(key)||0,n=prev+e.qtyMilli;if(!Number.isSafeInteger(n)||n>MAX_QTY)throw Error('جمع نامعتبر در ثبت‌ها وجود دارد.');totals.set(key,n);}
 const ordered=[...s.products].sort((a,b)=>(a.sourceRow||1e9)-(b.sourceRow||1e9)||a.name.localeCompare(b.name,'fa'));let append=ws.rowCount+1;const outputRows=[];for(const p of ordered){const r=p.sourceRow||append++;if(!p.sourceRow){const row=ws.getRow(r);row.getCell(m.name).value=p.name;if(m.code)row.getCell(m.code).value=p.code;if(m.tag)row.getCell(m.tag).value=p.tag;if(m.stock)row.getCell(m.stock).value=p.stock||'';}for(let round=1;round<=3;round++){const key=p.id+'|'+round;ws.getRow(r).getCell(countCols[round-1]).value=totals.has(key)?totals.get(key)/1000:null;}outputRows.push({product:p,row:r});}
 let detailsName='ریز شمارش‌ها',index=2;while(book.getWorksheet(detailsName))detailsName='ریز شمارش‌ها '+index++;const detail=book.addWorksheet(detailsName),productMap=new Map(s.products.map(p=>[p.id,p]));detail.views=[{rightToLeft:true}];detail.addRow(['شناسه ثبت','کد کالا','شماره تگ','نام کالا','نوبت','تعداد','شمارشگر اولیه','زمان ثبت','شماره ویرایش','آخرین اصلاح','سوابق اصلاح']);for(const e of [...s.entries].sort((a,b)=>a.createdAt.localeCompare(b.createdAt))){const p=productMap.get(e.productId);if(!p)throw Error('یک ثبت به کالای ناموجود متصل است.');detail.addRow([e.id,p.code,p.tag,p.name,e.round,e.qtyMilli/1000,e.operator,e.createdAt,e.revision,e.updatedAt||'',(e.changes||[]).map(c=>`${c.at} | ${c.by} | ${c.from/1000} → ${c.to/1000}`).join('\n')]);}detail.getRow(1).font={bold:true};detail.getColumn(4).width=55;detail.getColumn(2).width=24;detail.getColumn(3).width=18;detail.getColumn(6).numFmt='#,##0.###';
 const buffer=await book.xlsx.writeBuffer(),verify=new ExcelJS.Workbook();await verify.xlsx.load(buffer);const check=verify.getWorksheet(ws.id);for(const {product:p,row}of outputRows){if(m.code&&cellText(check.getRow(row).getCell(m.code),true)!==p.code)throw Error('کنترل کد کالا در خروجی موفق نبود.');for(let round=1;round<=3;round++){const actual=check.getRow(row).getCell(countCols[round-1]).value,key=p.id+'|'+round;if(totals.has(key)?Math.round(Number(actual)*1000)!==totals.get(key):actual!==null)throw Error('تعداد خروجی با ثبت‌های گوشی تطابق ندارد.');}}if(verify.getWorksheet(detailsName).rowCount!==s.entries.length+1)throw Error('ریز شمارش‌های خروجی کامل نیست.');return buffer;}
async function exportExcel(){if(exporting||saving)return;exporting=true;$('exportBtn').disabled=true;$('exportStatus').textContent='در حال ساخت و بررسی خروجی…';try{const s=await snapshot();if(!s.products.length)throw Error('هنوز کالایی وارد نشده است.');const buffer=await buildExcel(s);await saveFile(buffer,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',`انبارشمار-${safeName(COMPANY[s.settings.companyId])}-${safeName(s.settings.warehouse)}-${new Date().toISOString().slice(0,10)}.xlsx`);$('exportStatus').textContent=`خروجی شامل ${fmt(s.entries.length)} ثبت تا زمان ${new Date().toLocaleTimeString('fa-IR')} آماده شد.`;notify('خروجی آماده شد؛ ذخیره در Files را بررسی کنید.');}catch(e){$('exportStatus').textContent='خروجی ذخیره نشد: '+e.message;notify('خروجی ذخیره نشد: '+e.message,true);}finally{exporting=false;$('exportBtn').disabled=false;}}
async function checksum(data){const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(data)));return Array.from(new Uint8Array(hash),n=>n.toString(16).padStart(2,'0')).join('');}
async function backup(){if(exporting||saving)return;exporting=true;$('backupBtn').disabled=true;try{const s=await snapshot(),data={format:'anbarshomar-android-v1',exportedAt:new Date().toISOString(),settings:s.settings,products:s.products,entries:s.entries,raw:s.raw?{...s.raw,bytes:bytes64(s.raw.bytes)}:null},wrapped={data,sha256:await checksum(data)};await saveFile(new TextEncoder().encode(JSON.stringify(wrapped)),'application/json',`بکاپ-انبارشمار-${safeName(settings.warehouse)}-${Date.now()}.json`);notify('پشتیبان آماده شد؛ ذخیره در Files را بررسی کنید.');}catch(e){notify('پشتیبان ذخیره نشد: '+e.message,true);}finally{exporting=false;$('backupBtn').disabled=false;}}
function validateBackup(data){if(data?.format!=='anbarshomar-android-v1'||!Array.isArray(data.products)||!Array.isArray(data.entries)||!COMPANY[data.settings?.companyId]||typeof data.settings.warehouse!=='string'||typeof data.settings.operator!=='string'||typeof data.settings.period!=='string')throw Error('ساختار پشتیبان معتبر نیست.');if(data.products.length>20000||data.entries.length>200000)throw Error('پشتیبان بیش از اندازه بزرگ است.');const ids=new Set(),keys=new Set();for(const p of data.products){if(typeof p.id!=='string'||!p.id||ids.has(p.id)||typeof p.key!=='string'||keys.has(p.key)||typeof p.name!=='string'||!p.name||typeof p.code!=='string'||typeof p.tag!=='string'||(p.sourceRow!==null&&(!Number.isInteger(p.sourceRow)||p.sourceRow<2)))throw Error('فهرست کالاهای پشتیبان نامعتبر است.');ids.add(p.id);keys.add(p.key);}const entryIds=new Set(),totals=new Map();for(const e of data.entries){if(typeof e.id!=='string'||entryIds.has(e.id)||!ids.has(e.productId)||![1,2,3].includes(e.round)||!Number.isSafeInteger(e.qtyMilli)||e.qtyMilli<0||e.qtyMilli>MAX_QTY||!Number.isInteger(e.revision)||e.revision<1||typeof e.operator!=='string'||!Number.isFinite(Date.parse(e.createdAt)))throw Error('ثبت شمارش نامعتبر در پشتیبان است.');entryIds.add(e.id);const key=e.productId+'|'+e.round,n=(totals.get(key)||0)+e.qtyMilli;if(n>MAX_QTY)throw Error('جمع پشتیبان بیش از حد مجاز است.');totals.set(key,n);}if(data.raw&&(!data.raw.mapping?.name||!data.raw.mapping?.headerRow||typeof data.raw.bytes!=='string'))throw Error('فایل خام پشتیبان نامعتبر است.');return data;}
async function restore(file){if(!file)return;if(saving||exporting)throw Error('ابتدا عملیات جاری را تمام کنید.');if(file.size>60*1024*1024)throw Error('فایل پشتیبان بیش از حد بزرگ است.');const wrapper=JSON.parse(await file.text());if(!wrapper.sha256||await checksum(wrapper.data)!==wrapper.sha256)throw Error('فایل پشتیبان ناقص یا تغییرکرده است.');const s=validateBackup(wrapper.data);if(s.raw){s.raw.bytes=from64(s.raw.bytes);const wb=new ExcelJS.Workbook();await wb.xlsx.load(s.raw.bytes);if(!wb.getWorksheet(s.raw.mapping.sheetId))throw Error('برگه فایل خام بکاپ پیدا نشد.');}if(!confirm(`اطلاعات فعلی این برنامه جایگزین شود؟\nانبار پشتیبان: ${s.settings.warehouse}\nثبت‌ها: ${s.entries.length}\nابتدا از اطلاعات فعلی پشتیبان بگیرید.`))return;if(!confirm('تأیید نهایی: پشتیبان جایگزین اطلاعات فعلی همین گوشی شود؟'))return;saving=true;try{await write(['meta','products','entries'],tx=>{for(const name of ['meta','products','entries'])tx.objectStore(name).clear();tx.objectStore('meta').put({key:'settings',value:s.settings});if(s.raw)tx.objectStore('meta').put({key:'raw',value:s.raw});for(const p of s.products)tx.objectStore('products').add(p);for(const e of s.entries)tx.objectStore('entries').add(e);});await reload();showTab('count');notify('پشتیبان با موفقیت بازیابی شد.');}finally{saving=false;$('restoreFile').value='';}}
async function init(){try{if(!window.ExcelJS)throw Error('بخش اکسل برنامه بارگذاری نشد.');db=await openDB();await reload();for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>showTab(b.dataset.tab);$('saveSettings').onclick=()=>saveSettings().catch(e=>notify(e.message,true));$('round').onchange=()=>{currentRound=Number($('round').value);render();};$('search').oninput=renderSearch;$('searchMode').onchange=()=>{$('search').placeholder=$('searchMode').value==='tag'?'شماره تگ…':$('searchMode').value==='code'?'کد کالا…':'نام کالا…';renderSearch();};document.body.addEventListener('click',e=>{const pick=e.target.closest('[data-pick]'),edit=e.target.closest('[data-edit]');if(pick)showCount(pick.dataset.pick);if(edit)editEntry(edit.dataset.edit);});$('closeModal').onclick=closeModal;$('modal').addEventListener('cancel',e=>{if(saving)e.preventDefault();else selected=null;});$('manualBtn').onclick=showManual;$('importBtn').onclick=()=>beginImport().catch(e=>notify('ورود فایل انجام نشد: '+e.message,true));$('exportBtn').onclick=exportExcel;$('backupBtn').onclick=backup;$('restoreFile').onchange=e=>restore(e.target.files[0]).catch(err=>{notify('بازیابی انجام نشد: '+err.message,true);$('restoreFile').value='';});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!saving)reload().catch(e=>notify(e.message,true));});connectNativePicker($('rawFile'),'raw');connectNativePicker($('restoreFile'),'restore');showTab(settings.warehouse?'count':'settings');}catch(e){fail(e.message);}}

window.nativePickResult=(id,name,mime,data,error)=>{const p=nativePicks.get(id);if(!p)return;nativePicks.delete(id);if(error){p.reject(Error(error));return;}try{p.resolve(new File([from64(data)],name,{type:mime}));}catch(e){p.reject(e);}};
function connectNativePicker(input,kind){if(!window.AndroidFiles?.pick)return;input.addEventListener('click',async event=>{event.preventDefault();if(nativePicking)return;nativePicking=true;try{const id=uid(),file=await new Promise((resolve,reject)=>{nativePicks.set(id,{resolve,reject});try{window.AndroidFiles.pick(id,kind);}catch(e){nativePicks.delete(id);reject(e);}});const dt=new DataTransfer();dt.items.add(file);input.files=dt.files;input.dispatchEvent(new Event('change',{bubbles:true}));notify('فایل انتخاب شد: '+file.name);}catch(e){notify(e.message,true);}finally{nativePicking=false;}});}

window.addEventListener('DOMContentLoaded',init);
